#include "stdlib/blas/ext/base/ndarray/striu.h"
#include "stdlib/blas/ext/base/striu.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/ndarray/ctor/get_ptr.h"

/**
* Copies the upper triangular part of a single-precision floating-point matrix `A` to another matrix `B`.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a two-dimensional input ndarray corresponding to `A`.
*     -   a two-dimensional output ndarray corresponding to `B`.
*     -   a zero-dimensional ndarray specifying the diagonal below which to ignore.
*
* @param arrays    list containing ndarrays
*/
void stdlib_blas_ext_striu( const struct ndarray *arrays[] ) {
	const struct ndarray *A = arrays[ 0 ];
	const struct ndarray *B = arrays[ 1 ];
	const struct ndarray *k = arrays[ 2 ];

	const CBLAS_INT M = stdlib_ndarray_dimension( A, 0 );
	const CBLAS_INT N = stdlib_ndarray_dimension( A, 1 );

	const CBLAS_INT strideA1 = stdlib_ndarray_stride_elements( A, 0 );
	const CBLAS_INT strideA2 = stdlib_ndarray_stride_elements( A, 1 );
	const CBLAS_INT offsetA = stdlib_ndarray_offset_elements( A );

	const CBLAS_INT strideB1 = stdlib_ndarray_stride_elements( B, 0 );
	const CBLAS_INT strideB2 = stdlib_ndarray_stride_elements( B, 1 );
	const CBLAS_INT offsetB = stdlib_ndarray_offset_elements( B );

	const float *dataA = (const float *)stdlib_ndarray_data( A );
	float *dataB = (float *)stdlib_ndarray_data( B );

	int32_t k_value;
	stdlib_ndarray_get_int32( k, NULL, &k_value );

	API_SUFFIX(stdlib_strided_striu_ndarray)( M, N, (CBLAS_INT)k_value, dataA, strideA1, strideA2, offsetA, dataB, strideB1, strideB2, offsetB );
}
